def max_product_after_increment(digits):
    n = len(digits)
    if n == 1:
        return digits[0] + 1

    # Find the position of the first non-nine digit from the left
    first_non_nine = -1
    for i in range(n):
        if digits[i] != 9:
            first_non_nine = i
            break

    if first_non_nine == -1:
        # All digits are nine, incrementing any one will result in a product of 10^(n-1)
        return 10**(n-1)

    # Calculate the maximum product by incrementing the first non-nine digit
    max_product = 1
    for i in range(n):
        if i == first_non_nine:
            max_product *= (digits[i] + 1)
        else:
            max_product *= digits[i]

    return max_product

