    def maxStrength(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]

        positive_nums = [num for num in nums if num > 0]
        negative_nums = sorted([num for num in nums if num < 0])

        # If there are no positive numbers and less than 2 negative numbers, we can only use one number
        if not positive_nums and len(negative_nums) < 2:
            return max(nums)

