        n = len(s)

        # Calculate prefix and suffix inversion costs
        prefix_cost = [0] * (n + 1)
        suffix_cost = [0] * (n + 1)

        for i in range(1, n):
            if s[i - 1] != s[i]:
                prefix_cost[i] = prefix_cost[i - 1] + i
            else:
                prefix_cost[i] = prefix_cost[i - 1]

        for i in range(n - 2, -1, -1):
            if s[i + 1] != s[i]:
                suffix_cost[i] = suffix_cost[i + 1] + (n - i - 1)
            else:
                suffix_cost[i] = suffix_cost[i + 1]

        # Calculate the minimum cost to make all characters equal
        min_cost_0 = float('inf')
        min_cost_1 = float('inf')

        for i in range(n):
            if s[i] == '0':
                min_cost_0 = min(min_cost_0, prefix_cost[i] + suffix_cost[i])
